L21_1.m_VoiceFileName = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN_IN_TRAILER_4"
L21_1.m_Talk_KOREA = "세계를 만드는 법칙에 의해, 전부 정해져 있던 걸지도 모른다고."
L21_1.m_fTalkTime = 0.03
L21_1.m_bTalkCenterFadeIn = true
L21_1.m_Talk_JPN = "世界を作る法則によって、全部決まっていたのかもしれないって。"
L21_1.m_Talk_ENG = "Maybe everything was already decided by the law of creating a world."
L21_1.m_Talk_TWN = "也許一切都已經被創造世界的法則所決定了。"
L21_1.m_Talk_SCN = "也许一切都已经被创造世界的规则所决定了。"
L21_1.m_Talk_DEU = "Maybe everything was already decided by the law of creating a world."
L21_1.m_Talk_FRA = "Maybe everything was already decided by the law of creating a world."
