L23_1 = {}
L23_1.m_CutScenKey_Talk = "EP13_ACT4_STAGE5_END@13#Talk"
L23_1.m_CutScenProcessKey = 21
L23_1.m_CutScenID = 622
L23_1.m_CutScenStrID = "EP13_ACT4_STAGE5_END"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_SERIOUS"
L23_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_02"
L23_1.m_CharStrID = "INTERN_FENRIR_NEXT_NULL"
L23_1.m_Pos = "C"
L23_1.m_Talk_KOREA = "아니요. 저는 인간이에요."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "いいえ、私は人間です。"
L23_1.m_Talk_ENG = "No. I'm human."
L23_1.m_Talk_TWN = "不，我是人類。"
L23_1.m_Talk_SCN = "不，我是人类。"
L23_1.m_Talk_DEU = "No. I'm human."
L23_1.m_Talk_FRA = "No. I'm human."
L24_1 = {}
L24_1.m_CutScenKey_Talk = "EP13_ACT4_STAGE5_END@14#Talk"
L24_1.m_CutScenProcessKey = 22
L24_1.m_CutScenID = 622
L24_1.m_CutScenStrID = "EP13_ACT4_STAGE5_END"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "INTERN_FENRIR_NEXT_NULL"
L24_1.m_Pos = "C"
L24_1.m_Talk_KOREA = "인간은 누구나 다른 사람에게 도움을 받고 살아요."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "人間は誰だって、他の人に助けられながら生きています。"
L24_1.m_Talk_ENG = "And humans live with help from others."
L24_1.m_Talk_TWN = "人類無論是誰，都是依靠他人的幫助而生活的。"
L24_1.m_Talk_SCN = "人类无论是谁，都是依靠他人的帮助而生活的。"
L24_1.m_Talk_DEU = "And humans live with help from others."
L24_1.m_Talk_FRA = "And humans live with help from others."
L25_1 = {}
L25_1.m_CutScenKey_Talk = "EP13_ACT4_STAGE5_END@15#Talk"
L25_1.m_CutScenProcessKey = 23
L25_1.m_CutScenID = 622
L25_1.m_CutScenStrID = "EP13_ACT4_STAGE5_END"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "INTERN_FENRIR_NEXT_NULL"
L25_1.m_Pos = "C"
L25_1.m_Talk_KOREA = "힘들 때는 손을 내밀어도 괜찮아요. 그건 부끄러운 게 아니니까요."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "辛い時は手を伸ばしても大丈夫です。それは恥ずかしいことじゃありません。"
L25_1.m_Talk_ENG = "It's okay to reach out when you're struggling. There's nothing shameful about that."
L25_1.m_Talk_TWN = "困難的時候，伸出手來求助也沒關係。這並不是什麼？恥的事情。"
L25_1.m_Talk_SCN = "困难的时候，伸出手来求助也没关系。这并不是什么可耻的事情。"
L25_1.m_Talk_DEU = "It's okay to reach out when you're struggling. There's nothing shameful about that."
L25_1.m_Talk_FRA = "It's okay to reach out when you're struggling. There's nothing shameful about that."
L26_1 = {}
L26_1.m_CutScenKey_Talk = "EP13_ACT4_STAGE5_END@16#Talk"
L26_1.m_CutScenProcessKey = 24
L26_1.m_CutScenID = 622
L26_1.m_CutScenStrID = "EP13_ACT4_STAGE5_END"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_IDLE"
L26_1.m_CharStrID = "INTERN_FENRIR_NEXT_NULL"
L26_1.m_Pos = "C"
L26_1.m_Talk_KOREA = "대신, 도움을 받았다면 언젠가 그 도움을 돌려줄 수 있어야 해요."
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "その代わり、助けてもらったのなら、いつかそれを返せるようにならないといけないんです。"
L26_1.m_Talk_ENG = "But if you receive help, you have to return it someday."
L26_1.m_Talk_TWN = "相應的，如果得到了幫助，總有一天也要回報這份幫助。"
L26_1.m_Talk_SCN = "相应的，如果得到了帮助，总有一天也要回报这份帮助。"
L26_1.m_Talk_DEU = "But if you receive help, you have to return it someday."
L26_1.m_Talk_FRA = "But if you receive help, you have to return it someday."
