L28_1.m_CharScale = L29_1
L28_1.m_CharScaleTime = 0.01
L28_1.m_Talk_KOREA = "미나 선배, 에이미 씨, 펠리세트와 라이카… 모두 저를 구하기 위해 여기까지 와주었어요."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "ミナ先輩、エイミーさん、フェリセットとライカ……みんな私を助けるためにここまで来てくれました。"
L28_1.m_Talk_ENG = "Mina, Amy, Félicette, and Laika... they all came here to save me."
L28_1.m_Talk_TWN = "米娜前輩，艾米，費莉塞特和萊卡……大家都是為了救我才來到這裡的。"
L28_1.m_Talk_SCN = "美娜前辈，艾米小姐，菲利塞特和莱卡……大家都是为了救我才来到这里的。"
L28_1.m_Talk_DEU = "Mina, Amy, Félicette, and Laika... they all came here to save me."
L28_1.m_Talk_FRA = "Mina, Amy, Félicette, and Laika... they all came here to save me."
