L41_1.m_CharStrID = "INTERN_FENRIR_NEXT_NULL"
L42_1 = "클리파 허수 에너지와 세피라 신성 에너지는 마치 동전의 앞면과 뒷면 같은 힘이에요."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "クリファ虚数エネルギーとセフィラ神聖エネルギーは、まるでコインの裏表のような力です。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Qlipha Imaginary Energy and Sephira Divinity Energy are two sides of the same coin."
L41_1.m_Talk_ENG = L42_1
L42_1 = "逆卡巴拉虛數能量和生命樹神聖能量，就像硬幣的正反兩面一樣的力量。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "逆卡巴拉虚数能量和塞菲拉神圣能量就像硬币的正反两面一样的力量。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Qlipha Imaginary Energy and Sephira Divinity Energy are two sides of the same coin."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Qlipha Imaginary Energy and Sephira Divinity Energy are two sides of the same coin."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EP13_ACT4_STAGE5_END@54#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 91
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 622
L42_1.m_CutScenStrID = "EP13_ACT4_STAGE5_END"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_CharStrID = "INTERN_FENRIR_NEXT_NULL"
L43_1 = "따라서 당신이 클리파 허수 에너지를 통해, 자신의 심상을 반영한 클리파 영역을 만들었듯."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "だからあなたがクリファ虚数エネルギーを使って、自分の心象を反映したクリファ領域を作ったように、"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Just as you used the Qlipha Imaginary Energy to shape a domain that reflected your will."
L42_1.m_Talk_ENG = L43_1
L43_1 = "因此，就像你通過逆卡巴拉虛空能量創造了反映自己心象的逆卡巴拉領域一樣。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "因此，就像你通过逆卡巴拉虚空能量创造了反映自己心象的逆卡巴拉领域一样。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Just as you used the Qlipha Imaginary Energy to shape a domain that reflected your will."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Just as you used the Qlipha Imaginary Energy to shape a domain that reflected your will."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP13_ACT4_STAGE5_END@55#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 92
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 622
L43_1.m_CutScenStrID = "EP13_ACT4_STAGE5_END"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "INTERN_FENRIR_NEXT_NULL"
